insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p111', 'allemand', '3AS', 15, 111, 'L6 3AS p111 — Die Kommunikationsmittel (ouverture Lektion 6)', E'Lektion 6 — Die Kommunikationsmittel (ouverture)\nFotos : ein Mann am Computer mit Telefonhörer · Funkturm mit Parabolantennen · eine Frau am Telefon vor dem Computer.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p112', 'allemand', '3AS', 15, 112, 'L6 3AS p112 — Kommunikationsmittel : Text (Briefe/Jodeln/Rauchzeichen → Telefon 1876 → Handys/SMS) + Tabelle Früher/Heute', E'Was fällt Ihnen ein zu Kommunikationsmitteln ?\n1. Lesen Sie den folgenden Text.\nEin Leben ohne Fernsprechapparat scheint heute kaum denkbar. Doch es ging auch ohne.\nBis zum neunzehnten Jahrhundert waren die Menschen findig genug, sich mit Hilfe von Briefen, Jodeln, Pfeifsprachen und Rauchzeichen auch über große Distanzen zu verständigen. Aber nur sehr eingeschränkt.\nDas Bedürfnis, über lange Distanzen zu kommunizieren, war schon immer da. Die Möglichkeiten wurden aber erst 1861 geschaffen.\nDas Telefon, das von Graham Bell im Jahr 1876 erfunden war, ist das am meisten genutzte Kommunikationsmittel, ohne das wir im geschäftlichen als auch im privaten Bereich nicht mehr auskommen.\nDie Fernmeldetechnik hat das Leben mindestens genauso revolutioniert wie die Erfindung des Computers.\nMan sagt «die zweite Telefonrevolution begann mit den Handys. Mit diesen Erfindungen ist draht- und grenzenlose mobile Kommunikation keine Utopie mehr geworden».\nJugendliche mit flinkem Daumen verschicken weltweit inzwischen Milliarden SMS täglich. Auch Fotos, Videos und Musik treten per Handy ihre Reise um die Welt an.\n2. Ergänzen Sie die folgende Tabelle mit Informationen aus dem Text.\nFrüher | Heute', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p113', 'allemand', '3AS', 15, 113, 'L6 3AS p113 — Ergänzen (denkbar/einschränken/verständigen) + Synonyme + Antworten + Übersetzen', E'3. Ergänzen Sie. (denkbar · einschränken · verständigen · Bedürfnis · Utopie)\n- Dieser Mann ist stumm. Wir ………… uns durch Zeichen mit ihm.\n- Für die Jugendlichen ist das Leben ohne Handy nicht …………\n- Dank dem Internet ist das Reisen ohne Pass keine …………\n- Die Eltern ………… die Handykosten ihrer Kinder …………\n- Heutzutage hat der Mensch ein großes ………… nach Ruhe.\n4. Ersetzen Sie die hier unterstrichenen Wörter durch Synonyme aus dem Text.\n- Die Jugendlichen haben immer Lust zu kommunizieren.\n- Dieser Schüler hat immer kluge Ideen.\n- Die Eltern begrenzen die Ausgaben ihres Sohnes.\n- Die Kommunikationstechnik hat riesige Fortschritte gemacht.\n5. Antworten Sie.\n1. Wie tauschten die Menschen früher die Nachrichten aus ?\n2. Wann wurde zum ersten Mal das Telefon erfunden ?\n3. In welchem Bereich wird das Telefon gebraucht ?\n4. Welche Erfindung hat das Leben stark verändert ?\n6. Übersetzen Sie ins Arabische.\nFotos, Videos und Musik treten per Handy ihre Reise um die Welt an.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p114', 'allemand', '3AS', 15, 114, 'L6 3AS p114 — Erst eine SMS, dann Zähneputzen (Boris, 1440 SMS/Jahr) + Vorteile/Nachteile + R/F', E'Erst eine SMS, dann Zähneputzen\nNoch bevor die Zahnbürste morgens im Mund ist, wird schnell eine Kurznachricht, SMS, geschickt, spätestens aber auf dem Weg zum Schulbus. Im Unterricht bleibt das Handy aus - normalerweise - aber in den Pausen und nach der Schule wird es sofort eingeschaltet. Kommunikation rund um die Uhr, immer und überall erreichbar zu sein, ist auch für Jugendliche sehr wichtig.\n21 Milliarden SMS wurden im vergangenen Jahr in Deutschland geschickt, eine gigantische Zahl.\nNicht so überraschend, wenn man Boris kennen lernt. Boris ist 21 Jahre alt, geht auf ein technisches Gymnasium und verschickt gerne SMS. «Hundert SMS im Monat, das ist gar nichts» sagt er. Er tippt im Monat so 120 Kurznachrichten. Das macht 1440 im Jahr - alleine von Boris.\nAber Boris ist nicht alleine. 74 Prozent der 12 - bis 19 Jährigen haben nach der Studie «Jugend, Information, Multimedia 2001» ein Mobiltelefon.\nEin Handy hat viele Vorteile, aber auch hohe Kosten. Zu den SMS kommen bei Boris die täglichen Telefongespräche plus ab und zu ein neuer Klingelton, den er in Jugendzeitschriften unter teuren 0190 - Nummern bestellt, was den Stress bei den Eltern verursacht.\nBoris muss lange nachdenken, bis ihm überhaupt ein Freund einfällt, der noch kein Handy hat. Mit allen anderen schreibt er sich regelmäßig SMS, obwohl das ziemlich unpraktisch ist: Für die Frage «Gehen wir heute Abend ins Kino ?» drückt man über 60-mal die kleinen Tasten, allein für ein «S» viermal die Zahl 7.\n1. Ergänzen Sie die folgende Tabelle mit Informationen aus dem Text.\nVorteile des Handys | Nachteile des Handys\n2. Richtig oder falsch ? Kreuzen Sie an. (R/F)\n- Hundert SMS pro Monat sind sehr viel, sagt Boris.\n- Boris schreibt SMS und telefoniert auch jeden Tag.\n- Boris hat noch mehrere Freunde, die kein Handy haben.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p115', 'allemand', '3AS', 15, 115, 'L6 3AS p115 — Ergänzen (Handy) + Synonyme + Antworten + Adjektive mit -bar', E'3. Ergänzen Sie. (einschalten · Kosten · SMS · Mobiltelefon · verschicken)\n- Junge Leute ………… Hunderte Kurznachrichten im Monat.\n- Die Jugendlichen tauschen zahlreiche ……… aus.\n- Die Jugendlichen wollen ihre Handys im Unterricht lieber …………\n- Das Handy verursacht hohe …………\n- Viele Menschen haben heute ein …………\n4. Ersetzen Sie die hier unterstrichenen Wörter durch ein Synonym oder ein gleichbedeutendes Wort aus dem Text.\n- Die Wissenschaftler müssen überlegen, wie man den Computer ohne Schaden benutzen kann.\n- Der Computer ist eine riesige Erfindung.\n- Die Jugendlichen senden jeden Tag Kurznachrichten ab.\n5. Antworten Sie.\n1. Inwiefern werden die Jugendlichen von dem Handy beeinflusst ?\n2. Was ist wichtig für die Jugendlichen ?\n3. Wie viele Kurznachrichten schreibt Boris im Jahr ?\n4. Wozu gebraucht Boris sein Handy ?\n6. Bilden Sie Adjektive mit «bar».\n- erreichen → erreichbar\n- trinken → … · essen → … · sinken → … · denken → … · realisieren → … · brennen → … · lösen → … · genießen → … · lesen → … · kosten → …', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
